-- ============================================================
-- RBE · Demo Junio 2026 — EXPOSICIÓN
-- Semana: Lunes 22 → Sábado 27 de Junio 2026
-- Ejecutar DESPUÉS del script base y del script de abril
-- ============================================================
-- Rangos:
--   viajes  : 2000 – 2199
--   pagos   : 3000 – 3099
--   tickets : 7000 – 7999
-- ============================================================

USE rbe;

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM ticket        WHERE codigo  BETWEEN 7000 AND 7999;
DELETE FROM pago          WHERE numero  BETWEEN 3000 AND 3099;
DELETE FROM viaje_asiento WHERE viaje   BETWEEN 2000 AND 2199;
DELETE FROM viaje         WHERE numero  BETWEEN 2000 AND 2199;
ALTER TABLE viaje   AUTO_INCREMENT = 2000;
ALTER TABLE pago    AUTO_INCREMENT = 3000;
ALTER TABLE ticket  AUTO_INCREMENT = 7000;
SET FOREIGN_KEY_CHECKS = 1;

