-- ============================================================
UPDATE viaje_asiento va
JOIN ticket t ON t.asiento = va.asiento AND t.viaje = va.viaje
SET va.ocupado = 1
WHERE va.viaje BETWEEN 2000 AND 2130;

-- ============================================================
-- VERIFICACIÓN FINAL
-- ============================================================
SELECT '── VIAJES ──────────────────────────────────' AS info;
SELECT 'Total viajes junio'  AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 2000 AND 2130;
SELECT 'Finalizados'         AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 2000 AND 2130 AND estado=3;
SELECT 'En Ruta'             AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 2000 AND 2130 AND estado=2;
SELECT 'Disponibles'         AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 2000 AND 2130 AND estado=1;
SELECT 'Cancelados'          AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 2000 AND 2130 AND estado=4;
SELECT 'Retrasados'          AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 2000 AND 2130 AND estado=5;
SELECT '── TRANSACCIONES ────────────────────────────' AS info;
SELECT 'Pagos junio'         AS descripcion, COUNT(*) AS cantidad FROM pago   WHERE numero BETWEEN 3000 AND 3099;
SELECT 'Tickets junio'       AS descripcion, COUNT(*) AS cantidad FROM ticket WHERE codigo  BETWEEN 7000 AND 7999;
SELECT '── INGRESOS ─────────────────────────────────' AS info;
SELECT 'Recaudado lunes 22'  AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 3000 AND 3009;
SELECT 'Recaudado martes 23' AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 3010 AND 3019;
SELECT 'Recaudado miérc 24'  AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 3020 AND 3029;
SELECT 'Recaudado jueves 25' AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 3030 AND 3039;
SELECT 'Recaudado viernes 26'AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 3040 AND 3051;
SELECT 'TOTAL SEMANA'        AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 3000 AND 3099;
SELECT '── FILTROS DEMO ─────────────────────────────' AS info;
SELECT 'Viajes sábado 27 (en ruta)'     AS descripcion, COUNT(*) AS cantidad FROM viaje WHERE numero BETWEEN 2108 AND 2114 AND estado=2;
SELECT 'Viajes sábado 27 (disponibles)' AS descripcion, COUNT(*) AS cantidad FROM viaje WHERE numero BETWEEN 2115 AND 2130 AND estado=1;
SELECT 'Pasajeros con tickets esta semana' AS descripcion, COUNT(DISTINCT pasajero) AS cantidad FROM ticket WHERE codigo BETWEEN 7000 AND 7999;